// Получаем данные из предыдущей ноды
const name = $input.first().json.name;
const city = $input.first().json.city;
const course = $input.first().json.course;

// Собираем приветственное сообщение
const greeting = 'Привет, ' + name + '! Рады видеть тебя из ' + city + ' на курсе «' + course + '». Поехали! 🚀';

// Возвращаем результат
return [
  {
    json: {
      name: name,
      city: city,
      course: course,
      greeting: greeting
    }
  }
];
